function nav(){return `<header class="wrap nav"><a class="brand" href="/"><i>iptv</i>sreseller<span>.net</span></a><nav class="navlinks"><a href="/">Panel catalog</a><a href="/blog/">Guides</a><a href="/compare/">Compare</a><a href="/contact/">Contact</a></nav><a class="btn cyan" href="${W}" target="_blank">Order credits →</a></header>`}function foot(){return `<footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="/"><i>iptv</i>sreseller<span>.net</span></a><p>Panel comparisons, credit-duration guides and reseller onboarding information.</p></div><div><b>Explore</b><a href="/">All panels</a><a href="/compare/">Panel comparison</a><a href="/blog/">Knowledge hub</a></div><div><b>Support</b><a href="/contact/">Order & demo</a><a href="/about/">About</a><a href="/faq/">FAQ</a></div><div><b>Information</b><a href="/terms/">Terms</a><a href="/privacy/">Privacy</a><a href="/contact/">Contact sales</a></div></div><small>© 2026 iptvsreseller.net · B2B reseller information. Confirm availability, compatibility, content rights and pricing before ordering.</small></div></footer><aside class="float"><a class="wa" href="${W}" target="_blank">WhatsApp</a><a class="tg" href="${T}" target="_blank">Telegram</a></aside>`}function faq(items){return `<div class="faq">${items.map(x=>`<details><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div>`}
function card(p){return `<article class="card panel"><div class="panel-top"><div class="panel-mark" style="overflow:hidden;padding:3px">${panelLogo(p)}</div><span class="badge">${p[2]}</span></div><h3>${p[1]}</h3><p class="server-desc">${p[7]}</p><div class="tags">${p[3].split(', ').map(x=>`<span class="tag">${x}</span>`).join('')}</div><p class="catalog-stats">📺 ${p[4]} live · 🎬 ${p[5]} movies · 📼 ${p[6]} series</p><div class="card-actions"><a href="/panels/${p[0]}/">View panel & credits →</a><a class="trial" href="${W}" target="_blank">Get free playlist trial →</a></div></article>`}
function home(){let qs=[['Which IPTV reseller panel is best?','Choose based on your customers’ region, device mix, catalog preference and the panel-specific credit system. Request a controlled demo before buying.'],['How do reseller credits work?','Credits are redeemed against a supplier-defined customer duration. Each panel page shows its supplied conversion table.'],['Why do catalog counts matter?','Live channel, movie and series counts help compare scale. Treat them as availability snapshots and verify current figures during the demo process.']];return `${nav()}<main><section class="hero"><div class="wrap"><div class="eyebrow">B2B IPTV & OTT reseller platform</div><h1>Sell with a <em>panel built</em> for your customers.</h1><p class="lead">Compare 15 IPTV and OTT reseller panels, supplied catalog counts and exact credit-duration systems—then start onboarding through WhatsApp or Telegram.</p><div class="actions"><a class="btn green" href="${W}" target="_blank">WhatsApp: get credit rates</a><a class="btn ghost" href="${T}" target="_blank">Telegram: request demo</a></div><div class="trust"><span><b>●</b>15 panel options</span><span><b>●</b>Credit-duration tables</span><span><b>●</b>Catalog data</span><span><b>●</b>Reseller support</span></div></div></section><section class="section"><div class="wrap"><div class="section-head"><div class="eyebrow">Panel catalog</div><h2>Compare panel coverage, catalog scale and credit systems.</h2><p class="sub">Counts are supplied catalog snapshots. Availability changes; verify all current figures during your demo.</p></div><div class="filters"><button class="filter active" data-filter="all">All panels</button><button class="filter" data-filter="France">France</button><button class="filter" data-filter="UK">UK</button><button class="filter" data-filter="US">US</button><button class="filter" data-filter="Europe">Europe</button><button class="filter" data-filter="MENA">MENA</button><button class="filter" data-filter="Sports">Sports</button><button class="filter" data-filter="4K">4K / VOD</button><button class="filter" data-filter="Stable">Stability</button></div><div class="grid panels" id="panelGrid"></div></div></section><section class="section alt"><div class="wrap"><div class="calculator"><div><div class="eyebrow">Margin planner</div><h2>Estimate monthly gross margin.</h2><p class="sub">Planning illustration only; request current wholesale pricing for a real quote.</p><div class="field"><label>Active customers <output id="cust">50</output></label><input id="customers" type="range" min="10" max="500" value="50" step="10"></div><div class="field"><label>Margin per customer <output id="margin">$5</output></label><input id="marginRange" type="range" min="2" max="20" value="5"></div></div><aside class="result"><small>Illustrative monthly gross margin</small><strong id="profit">$250</strong><small id="profitNote">50 customers × $5 average margin</small><a class="btn cyan" href="${W}" target="_blank" style="margin-top:20px">Get a wholesale quote →</a></aside></div></div></section><section class="section alt"><div class="wrap"><div class="section-head"><div class="eyebrow">Reseller knowledge</div><h2>Direct answers for panel buyers.</h2></div>${faq(qs)}</div></section><section class="cta"><div class="wrap"><div class="eyebrow">Ready to choose?</div><h2>Ask for current credit rates, test access and onboarding details.</h2><a class="btn green" href="${W}" target="_blank">Speak to reseller sales</a></div></section></main>${foot()}${json({'@context':'https://schema.org','@type':'Organization',name:'iptvsreseller.net',url:'https://iptvsreseller.net'})}${json({'@context':'https://schema.org','@type':'FAQPage',mainEntity:qs.map(x=>({'@type':'Question',name:x[0],acceptedAnswer:{'@type':'Answer',text:x[1]}}))})}`}
function panel(p){let [slug,name,badge,regions,live,movies,series,desc,credits]=p;document.title=`Buy ${name} Reseller Panel Credits | iptvsreseller.net`;let m=document.querySelector('meta[name=description]')||document.head.appendChild(Object.assign(document.createElement('meta'),{name:'description'}));m.content=desc;let qs=[['What are the '+name+' credit durations?',credits.map(x=>x[0]+' = '+x[1]).join('; ')+'. Confirm current availability and terms with sales.'],['What catalog data is listed for '+name+'?',`The published snapshot lists ${live} live channels, ${movies} movies and ${series} series where supplied. Catalog availability may change and should be verified during a demo.`],['Which apps can resellers discuss?','Typical setup discussions include Tivimate, IPTV Smarters Pro, IBO Player, XCIPTV and STB Emulator. Compatibility must be confirmed per app, device and plan.']];return `${nav()}<main><div class="wrap crumb"><a href="/">Home</a> / <a href="/">Panels</a> / ${name}</div><section class="panelhero"><div class="wrap"><div class="eyebrow">${badge} · B2B reseller panel</div><h1>Buy ${name} Reseller Panel Credits</h1><p class="lead">${desc} Review catalog scale, the credit system and target regions before requesting an onboarding demo.</p><div class="actions"><a class="btn green" href="${W}" target="_blank">Request ${name} demo</a><a class="btn ghost" href="${T}" target="_blank">Ask on Telegram</a></div><div class="statline"><span><b>Target regions</b>${regions}</span><span><b>Panel profile</b>${badge}</span><span><b>Apps</b>Tivimate · Smarters · IBO</span></div></div></section><section class="section"><div class="wrap"><div class="section-head"><div class="eyebrow">Catalog snapshot</div><h2>${name} content scale at a glance.</h2><p class="sub">Supplier-provided figures. They are an inventory snapshot, not a guarantee, and should be reconfirmed during testing.</p></div><div class="grid specs"><article class="card metric"><div>📺</div><strong>${live}</strong><span>Live TV channels</span></article><article class="card metric"><div>🎬</div><strong>${movies}</strong><span>Movies</span></article><article class="card metric"><div>📼</div><strong>${series}</strong><span>Series</span></article></div></div></section><section class="section alt"><div class="wrap"><div class="section-head"><div class="eyebrow">Credit system</div><h2>${name} credit-to-duration table.</h2><p class="sub">Use this as your reseller planning guide. Credit values and availability are subject to live confirmation.</p></div><div style="overflow:auto"><table class="matrix"><thead><tr><th>Credit amount</th><th>Customer duration</th><th>Reseller action</th></tr></thead><tbody>${credits.map(x=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td><a class="check" href="${W}" target="_blank">Ask for current price →</a></td></tr>`).join('')}</tbody></table></div></div></section><section class="section"><div class="wrap"><div class="section-head"><div class="eyebrow">Technical checklist</div><h2>Plan a cleaner customer experience.</h2></div><div class="grid specs"><article class="card"><div class="icon">01</div><h3>Test region first</h3><p>${regions} are listed target regions. Test with your real customer location before scaling.</p></article><article class="card"><div class="icon">02</div><h3>Validate client apps</h3><p>Confirm current setup instructions for Tivimate, IPTV Smarters Pro, IBO Player, XCIPTV and STB Emulator.</p></article><article class="card"><div class="icon">03</div><h3>Confirm live capacity</h3><p>Ask sales how available capacity, load distribution and service monitoring are handled for your tier.</p></article></div></div></section><section class="section alt"><div class="wrap"><div class="section-head"><div class="eyebrow">Panel FAQ</div><h2>${name} reseller questions.</h2></div>${faq(qs)}</div></section></main>${foot()}${json({'@context':'https://schema.org','@type':'Product',name:`${name} Reseller Panel Credits`,description:desc,offers:{'@type':'Offer',availability:'https://schema.org/PreOrder',url:`https://iptvsreseller.net/panels/${slug}/`}})}${json({'@context':'https://schema.org','@type':'Service',name:`${name} reseller onboarding`,areaServed:regions.split(', ')})}${json({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:'https://iptvsreseller.net/'},{'@type':'ListItem',position:2,name:'Panels',item:'https://iptvsreseller.net/'},{'@type':'ListItem',position:3,name:name,item:`https://iptvsreseller.net/panels/${slug}/`} ]})}${json({'@context':'https://schema.org','@type':'FAQPage',mainEntity:qs.map(x=>({'@type':'Question',name:x[0],acceptedAnswer:{'@type':'Answer',text:x[1]}}))})}`}
function page(title,eyebrow,body){return `${nav()}<main class="wrap article"><div class="crumb"><a href="/">Home</a> / ${title}</div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${body}</main>${foot()}`}
function blog(){return page('IPTV & OTT Reseller Knowledge Hub','Reseller playbook',`<p class="lead">Clear guides for operators comparing panels, credit duration systems, supported apps and regional fit.</p><h2>How to compare a reseller panel</h2><p class="answer"><strong>Direct answer:</strong> Match customer geography, device mix, catalog preference and the supplied credit system. Request a controlled demo before buying credits.</p><h2>Understanding credit systems</h2><p>Credits represent a supplier-defined customer duration. Some panels use whole-credit monthly increments, others use micro-credits, while Max OTT has a five-tier duration model. Always use the panel-specific table rather than assuming a conversion.</p><h2>Client setup checklist</h2><ul><li>Confirm the customer’s app and device version.</li><li>Verify compatibility before promising support.</li><li>Use only credentials and media sources you are authorized to distribute.</li><li>Test customer playback and setup in the actual target region.</li></ul>`) }function compare(){return page('IPTV Reseller Panel Comparison','Comparison matrix',`<p class="lead">A structured directory of supplied catalog snapshots and commercial credit systems.</p><div style="overflow:auto"><table class="matrix"><thead><tr><th>Panel</th><th>Focus</th><th>Live TV</th><th>Movies</th><th>Series</th><th>Credits</th></tr></thead><tbody>${panels.map(p=>`<tr><td><a class="check" href="/panels/${p[0]}/">${p[1]}</a></td><td>${p[2]}</td><td>${p[4]}</td><td>${p[5]}</td><td>${p[6]}</td><td>${p[8].map(x=>x[0]).join(', ')}</td></tr>`).join('')}</tbody></table></div><p>Figures are supplier-provided snapshots and should be confirmed before purchase.</p>`) }function contact(){return page('Order Credits & Request a Panel Demo','Reseller desk',`<p class="lead">Send your audience region, target panel and required customer duration. The reseller desk will confirm current credit pricing, catalog availability and onboarding steps.</p><div class="actions"><a class="btn green" href="${W}" target="_blank">WhatsApp order request</a><a class="btn cyan" href="${T}" target="_blank">Telegram sales desk</a></div><h2>What to include in your message</h2><ul><li>Panel name and target region</li><li>Approximate customer volume</li><li>Preferred credit duration</li><li>Customer app/device setup requirements</li></ul>`) }function legal(title,copy){return page(title,'Information',`<p>${copy}</p><h2>Responsible reseller operations</h2><p>Confirm availability, pricing, compatibility and all applicable distribution rights before you offer a product to customers.</p>`)}
function renderGrid(f='all'){let e=document.getElementById('panelGrid');if(!e)return;e.innerHTML=panels.filter(p=>f==='all'||p[3].includes(f)||p[2].includes(f)||(f==='4K'&&(p[2].includes('4K')||p[2].includes('VOD')))).map(card).join('')}let path=location.pathname.replace(/\/$/,'')||'/',p=panels.find(x=>path===`/panels/${x[0]}`);document.getElementById('app').innerHTML=p?panel(p):path==='/blog'?blog():path==='/compare'?compare():path==='/contact'?contact():path==='/about'?page('About iptvsreseller.net','B2B information platform','<p class="lead">A clear information platform for panel comparisons, credit-duration guides and direct reseller onboarding.</p>'):path==='/privacy'?legal('Privacy Policy','Contact details shared through WhatsApp or Telegram are handled by those services under their own policies. Avoid sending sensitive information in an initial inquiry.'):path==='/terms'?legal('Terms of Use','Panel descriptions, catalog counts and credit systems are informational snapshots. Availability, application compatibility, commercial pricing and content rights must be confirmed before any order.'):path==='/faq'?page('Reseller FAQ','Answers',faq([['How do I order credits?','Choose a panel and contact sales with your region and desired duration.'],['Are catalog figures fixed?','No. Catalog data is a supplier-provided snapshot and should be reconfirmed during a current demo.'],['Can I use every app?','No. Validate client application and device compatibility before onboarding customers.']])):home();if(path==='/')renderGrid();document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderGrid(b.dataset.filter)});let a=document.getElementById('customers'),b=document.getElementById('marginRange');if(a&&b){let u=()=>{cust.textContent=a.value;margin.textContent='$'+b.value;profit.textContent='$'+(+a.value*+b.value);profitNote.textContent=`${a.value} customers × $${b.value} average margin`};a.oninput=b.oninput=u;u()}
